def countableCZeroProductEquiv [Countable ι] [Countable κ] [Infinite ι] :
    (C₀(ι, 𝕜) × C₀(κ, 𝕜)) ≃L[𝕜] JFA.cZero 𝕜 :=
  cZeroProductNumberingEquiv (Classical.choice (inferInstance : Nonempty ((ι ⊕ κ) ≃ ℕ)))

